import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for this card label
  const group = new THREE.Group();

  // Timelines to track for cleanup
  const timelines = [];

  // Create text label: "Pricing 3"
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textContent.find(item => item.text === 'Pricing 3') || 
                   { text: 'Pricing 3', fontSize: 39, color: '#e8ecf2' };

  const textMesh = ctx.fontAtlas.createText(String(textItem.text), {
    fontSize: textItem.typography?.fontSize ?? 39,
    color: textItem.color ?? '#e8ecf2',
    align: 'center'
  });
  textMesh.position.z = 0.05;
  group.add(textMesh);

  // Create backdrop plane with engineered gradient
  const planeGeom = new THREE.PlaneGeometry(1.2, 0.35);

  // Gradient material: dark surface to slightly lighter
  const gradientNode = mix(
    color('#0b0b10'),  // surface (dark base)
    color('#16161d'),  // ink (slightly lighter)
    uv().y           // vertical gradient
  );

  const planeMat = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    transparent: true,
    opacity: 0.95
  });

  const plane = new THREE.Mesh(planeGeom, planeMat);
  plane.position.z = 0.02;
  group.add(plane);

  // No cinematic primitives to apply (node ships without primitive)

  // Setup cleanup
  group.userData.cleanup = function() {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    // Dispose geometries and materials
    if (planeGeom) planeGeom.dispose();
    if (planeMat) planeMat.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  group.userData.handlers = {};

  return group;
}
